/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[
    error_codes::FACE_ALREADY_PLACED,
    error_codes::UNRESOLVED_REFERENCE,
    error_codes::VERSION_CONFLICT,
];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `persona/world/put:faceAlreadyPlaced`
    ///
    /// One or more of the listed `faceIds` already belongs to a different world. The details name each offending profile and the world currently holding it, so a producer can offer to move it rather than guessing. The world is not written.
    ///
    /// Declared `retryable: false`.
    pub const FACE_ALREADY_PLACED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "persona/world/put:faceAlreadyPlaced",
        retryable: false,
    };
    /// `persona/world/put:unresolvedReference`
    ///
    /// A listed `faceId` or `attributeId` names a record the holder does not hold. The details name them. The world is not written — an arrangement referring to something that never existed is a typo, and accepting it silently makes the typo permanent.
    ///
    /// Declared `retryable: false`.
    pub const UNRESOLVED_REFERENCE: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "persona/world/put:unresolvedReference",
        retryable: false,
    };
    /// `persona/world/put:versionConflict`
    ///
    /// The `expectedVersion` precondition failed. Details carry the maintainer's current version.
    ///
    /// Declared `retryable: false`.
    pub const VERSION_CONFLICT: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "persona/world/put:versionConflict",
        retryable: false,
    };
}
#[cfg(test)]
mod conformance {
    //! Round-trip tests harvested from the spec's `spec.md`,
    //! plus a `rejects_invalid_examples` test for any fixtures
    //! in `payload.invalid-examples.json` (validate feature).
    #[test]
    fn request_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000001\",\n  \"type\": \"https://trusttasks.org/spec/persona/world/put/1.0#request\",\n  \"issuer\": \"did:example:holder\",\n  \"recipient\": \"did:example:agent\",\n  \"issuedAt\": \"2026-01-01T00:00:00Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000ff\",\n  \"payload\": {\n    \"name\": \"Work\",\n    \"colour\": \"teal\",\n    \"icon\": \"💼\",\n    \"faceIds\": [\"01J8XR3QK9V0000000000000A1\", \"01J8XR3QK9V0000000000000A2\"],\n    \"attributeIds\": [\"01J8XR3QK9V0000000000000B7\"],\n    \"expectedVersion\": 0\n  }\n}\n";
        let doc: crate::TrustTask<super::Payload> =
            serde_json::from_str(JSON).expect("deserialize request example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "request example failed round-trip");
    }
    #[test]
    fn response_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000002\",\n  \"type\": \"https://trusttasks.org/spec/persona/world/put/1.0#response\",\n  \"issuer\": \"did:example:agent\",\n  \"recipient\": \"did:example:holder\",\n  \"issuedAt\": \"2026-01-01T00:00:01Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000ff\",\n  \"payload\": {\n    \"worldId\": \"01J8XR3QK9V0000000000000C4\",\n    \"version\": 1,\n    \"created\": true,\n    \"createdAt\": \"2026-01-01T00:00:01Z\",\n    \"updatedAt\": \"2026-01-01T00:00:01Z\"\n  }\n}\n";
        let doc: crate::TrustTask<super::Response> =
            serde_json::from_str(JSON).expect("deserialize response example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "response example failed round-trip");
    }
}
